    public final String id;
    public final String title;
    public final String trade;
    public final String icon;
    public final List<Line> lines;
    LyPage(String id, String title, boolean trade, String icon, List<Line> lines) { this.id = id; this.title = title; if (trade) this.trade = id; else this.trade = null; this.icon = icon; this.lines = lines; }
    public LyPage target(int button) {
        if (this == MAIN) return button == 0 ? SNOWDAE : null;
        if (button != 1 && button != 2) return null;
        return TRADES.get(Math.floorMod(TRADES.indexOf(this) + (button == 1 ? 1 : -1), TRADES.size()));
    }
    public record Line(String key, int x, int y, int color, int spacing) { public Line(String key, int x, int y, int color) { this(key, x, y, color, 0); } }
